SELECT rapidfuzz_qratio('this is a test', 'this is a new test!!!') AS q,
       rapidfuzz_qratio('', '') AS q_empty,
       rapidfuzz_ratio('', '') AS ratio_empty;

SELECT substr(s, a.s1_start + 1, a.s1_end - a.s1_start) AS matched
FROM (SELECT 'the quick brown fox' AS s,
             rapidfuzz_partial_ratio_alignment(s, 'quack') AS a);
